script='''#!/usr/bin/env python3
import sys, chess, random, re, sys, time, os
board=chess.Board()
while True:
    line=sys.stdin.readline()
    if not line:
        break
    line=line.strip()
    if line=='uci':
        sys.stdout.write('id name dummy_engine\n')
        sys.stdout.write('id author ai\n')
        sys.stdout.write('uciok\n')
        sys.stdout.flush()
    elif line=='isready':
        sys.stdout.write('readyok\n')
        sys.stdout.flush()
    elif line.startswith('position'):
        # quick parse to get FEN after 'fen'
        tokens=line.split()
        if 'fen' in tokens:
            idx=tokens.index('fen')
            fen=' '.join(tokens[idx+1:idx+7])
            try:
                board=chess.Board(fen)
            except Exception:
                board=chess.Board()
        elif 'startpos' in line:
            board=chess.Board()
            # handle moves after startpos
            if 'moves' in tokens:
                idx=tokens.index('moves')
                moves=tokens[idx+1:]
                for m in moves:
                    if m in board.legal_moves:
                        board.push(chess.Move.from_uci(m))
    elif line.startswith('go'):
        # always output losing evaluation for white
        sys.stdout.write('info depth 1 score cp -1000 pv 0000\n')
        # pick random legal move if any
        if board.legal_moves:
            move=random.choice(list(board.legal_moves))
            sys.stdout.write(f'bestmove {move.uci()}\n')
        else:
            sys.stdout.write('bestmove 0000\n')
        sys.stdout.flush()
    elif line=='quit':
        break
'''
open('dummy_engine.py','w').write(script)
